const WORKFLOW_GUARD_REFUSAL: &str = "refusing to allow a GitHub App to create or update workflow";

fn push_tag(
    runner: &dyn CommandRunner,
    root: &Path,
    endpoint: &str,
    operation: &TagOperation,
) -> Result<(), GraphError> {
    let push_args = ["push", endpoint, operation.name.as_str()];
    let pushed = runner.run_with_timeout(programs::GIT, &push_args, root, timeouts::GIT_PUSH)?;
    if pushed.exit_code == Some(0) {
        return Ok(());
    }
    if pushed.stderr.contains(WORKFLOW_GUARD_REFUSAL) {
        return Err(GraphError::ReleaseTagPushRefusedWorkflowGuard {
            tag: operation.name.as_str().to_owned(),
            target: operation.target.as_str().to_owned(),
        });
    }
    Err(GraphError::ReleaseCommand {
        program: programs::GIT.to_string(),
        args: push_args.iter().map(ToString::to_string).collect(),
        failure: CommandFailure::NonZeroExit {
            exit_code: pushed.exit_code,
            stderr: pushed.stderr,
        },
    if output.success() {
        return if reports_version(&output.stdout, version) {
            settled(ProviderObservationV1::Exact {
                evidence: ProviderEvidenceV1::RegistryVersion {
                    version: version.clone(),
                    checksum: None,
                    yanked: None,
                },
            })
        } else {
            transient(ProviderIndeterminateCause::MalformedResponse, None)
        };
    }
    if output.exit_code == Some(101) && output.stderr.contains(&format!("could not find `{spec}`")) {
        return settled(ProviderObservationV1::Absent);
    }
    transient(ProviderIndeterminateCause::CommandFailed, None)
}

/// The value of the `repository:` line `cargo info` prints, if the crate has one.
pub(super) fn cargo_info_repository(stdout: &str) -> Option<String> {
    stdout
        .lines()
        .find_map(|line| line.trim().strip_prefix("repository:"))
        .map(|value| value.trim().to_owned())
        .filter(|value| !value.is_empty())
}

/// Whether cargo's `version: X ...` line names exactly the requested version.
pub(super) fn reports_version(stdout: &str, version: &Version) -> bool {
    stdout.lines().any(|line| {
        line.trim()
            .strip_prefix("version: ")
            .and_then(|rest| rest.strip_prefix(version.render()))
            .is_some_and(|rest| rest.is_empty() || rest.starts_with(char::is_whitespace))
    })
}
/// `callisto.toml` counts), else the outermost package manifest so vendored packages can't shadow it.
///
/// The toplevel comes from `git rev-parse --show-toplevel` (via `runner`), not a hand-rolled
/// walk for a `.git` entry -- `git` alone honors `GIT_DIR`/`GIT_WORK_TREE`/
/// `GIT_CEILING_DIRECTORIES` the way every other Git-aware tool does.
pub fn find_workspace_root(start: &Path, runner: &dyn CommandRunner) -> Result<PathBuf, LocateError> {
    let canonical = dunce::canonicalize(start).unwrap_or_else(|_| start.to_path_buf());
    let toplevel = GitAccess::new(&canonical, runner).toplevel().map_err(|e| match &e {
        VcsError::Git(message) if message.to_lowercase().contains("not a git repository") => {
            LocateError::NotAGitRepository {
                start: start.to_path_buf(),
            }
        }
        _ => LocateError::from(e),
    })?;
    let range = || canonical.ancestors().take_while(|dir| dir.starts_with(&toplevel));
    for dir in range() {
        if is_workspace_root(dir)? {
            return Ok(dir.to_path_buf());
        }
    }

