        return Ok(None);
    }
    if !output.success() {
        return Err(probe_failed(&args, &self.root, &output));
    }
    let sha_str = output.stdout_trimmed();
    if sha_str.is_empty() {
        return Ok(None);
    }
    Ok(CommitSha::parse(sha_str).ok())
